class Solution {
    public String crackSafe(int n, int k) {
        if (n == 1) {
            StringBuilder single = new StringBuilder();
            for (int digit = 0; digit < k; digit++) {
                single.append(digit);
            }
            return single.toString();
        }

        String start = "0".repeat(n - 1);
        Set<String> visited = new HashSet<>();
        StringBuilder sequence = new StringBuilder();
        dfs(start, k, visited, sequence);
        sequence.append(start);
        return sequence.toString();
    }

    private void dfs(String node, int k, Set<String> visited, StringBuilder sequence) {
        for (int digit = 0; digit < k; digit++) {
            String edge = node + digit;
            if (visited.add(edge)) {
                dfs(edge.substring(1), k, visited, sequence);
                sequence.append(digit);
            }
        }
    }
}

import java.util.*;

class Solution {
    public String crackSafe(int n, int k) {
        if (n == 1) {
            StringBuilder single = new StringBuilder();
            for (int digit = 0; digit < k; digit++) {
                single.append(digit);
            }
            return single.toString();
        }

        String start = "0".repeat(n - 1);
        Set<String> visited = new HashSet<>();
        Deque<Frame> stack = new ArrayDeque<>();
        StringBuilder sequence = new StringBuilder();
        stack.push(new Frame(start, -1));

        while (!stack.isEmpty()) {
            Frame top = stack.peek();
            if (top.nextDigit + 1 < k) {
                top.nextDigit++;
                int digit = top.nextDigit;
                String edge = top.node + digit;
                if (visited.add(edge)) {
                    stack.push(new Frame(edge.substring(1), -1));
                }
            } else {
                Frame done = stack.pop();
                if (!stack.isEmpty()) {
                    sequence.append(done.node.charAt(done.node.length() - 1));
                }
            }
        }

        sequence.append(start);
        return sequence.toString();
    }

    private static final class Frame {
        private final String node;
        private int nextDigit;

        private Frame(String node, int nextDigit) {
            this.node = node;
            this.nextDigit = nextDigit;
        }
    }
}

class Solution {
    private int k;
    private int mod;
    private boolean[] seen;
    private StringBuilder sequence;

    public String crackSafe(int n, int k) {
        this.k = k;
        if (n == 1) {
            StringBuilder single = new StringBuilder();
            for (int digit = 0; digit < k; digit++) {
                single.append(digit);
            }
            return single.toString();
        }

        mod = 1;
        for (int i = 0; i < n - 1; i++) {
            mod *= k;
        }
        seen = new boolean[mod * k];
        sequence = new StringBuilder();
        dfs(0);
        for (int i = 0; i < n - 1; i++) {
            sequence.append('0');
        }
        return sequence.toString();
    }

    private void dfs(int node) {
        for (int digit = 0; digit < k; digit++) {
            int edge = node * k + digit;
            if (!seen[edge]) {
                seen[edge] = true;
                dfs(edge % mod);
                sequence.append(digit);
            }
        }
    }
}

class Solution {
    private int n;
    private int k;
    private int[] a;
    private StringBuilder sequence;

    public String crackSafe(int n, int k) {
        this.n = n;
        this.k = k;
        a = new int[n * k + 1];
        sequence = new StringBuilder();
        deBruijn(1, 1);
        for (int i = 0; i < n - 1; i++) {
            sequence.append('0');
        }
        return sequence.toString();
    }

    private void deBruijn(int t, int p) {
        if (t > n) {
            if (n % p == 0) {
                for (int i = 1; i <= p; i++) {
                    sequence.append(a[i]);
                }
            }
            return;
        }

        a[t] = a[t - p];
        deBruijn(t + 1, p);
        for (int j = a[t - p] + 1; j < k; j++) {
            a[t] = j;
            deBruijn(t + 1, t);
        }
    }
}

import java.util.*;

class Solution {
    public String crackSafe(int n, int k) {
        StringBuilder answer = new StringBuilder();
        for (int i = 0; i < n; i++) {
            answer.append('0');
        }

        Set<String> seen = new HashSet<>();
        seen.add(answer.toString());
        int total = 1;
        for (int i = 0; i < n; i++) {
            total *= k;
        }
        search(answer, seen, total, n, k);
        return answer.toString();
    }

    private boolean search(StringBuilder answer, Set<String> seen, int total, int n, int k) {
        if (seen.size() == total) {
            return true;
        }

        String prefix = answer.substring(answer.length() - n + 1);
        for (int digit = 0; digit < k; digit++) {
            String next = prefix + digit;
            if (seen.add(next)) {
                answer.append(digit);
                if (search(answer, seen, total, n, k)) {
                    return true;
                }
                answer.deleteCharAt(answer.length() - 1);
                seen.remove(next);
            }
        }
        return false;
    }
}
